//#############################################################################
//# Function: Generic counter                                                 #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_counter
  #(parameter N   = 32,       // width of data inputs
    parameter SYN = "TRUE",   // synthesizable
    parameter TYPE = "DEFAULT"// implementation type
    )
   (
    //inputs
    input 	       clk, // clk input
    input 	       in, // input to count
    input 	       en, // enable counter
    input 	       dec,//1=decrement, 0 = increment
    input 	       autowrap, //auto wrap counter
    input 	       load, // load counter
    input [N-1:0]      load_data, // input data to load
    //outputs
    output reg [N-1:0] count, // count value
    output 	       wraparound // wraparound indicator
    );

   wire [N-1:0]	 inb;
   wire [N-1:0]  count_in;

   //Increment decrement option
   assign inb[N-1:0] = dec ? {{(N-1){1'b1}},~in} : {{(N-1){1'b0}},in};
   assign cin        = dec ? 1'b1 : 1'b0;

   // counter
   always @(posedge clk)
     if(load)
       count[N-1:0] <= load_data[N-1:0];
     else if (en & ~(wraparound & ~autowrap))
       count[N-1:0] <= count_in[N-1:0];

   assign wraparound = (dec & en & ~(|count[N-1:0])) |
		       (~dec & en & (&count[N-1:0]));

   // Soft/hard adder
   generate
      if(SYN == "TRUE")  begin
	 assign count_in[N-1:0] =count[N-1:0] + inb[N-1:0];
      end
      else begin
	 asic_add #(.TYPE(TYPE),
		    .N(N))
	 asic_add (// Outputs
		   .sum		(cout_in[N-1:0]),
		   .carry	(),
		   .cout	(),
		   // Inputs
		   .a		(count[N-1:0]),
		   .b		(in_mux[N-1:0]),
		   .k		({(N){1'b0}}),
		   .cin		(cin));
      end
   endgenerate

endmodule // oh_counter

//#############################################################################
//# Function: Barrel shifter                                                  #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_shift
  #(parameter N   = 32,         // Operator width (8,16,32,64,128)
    parameter S    = $clog2(N), // stages=shift width
    parameter SYN = "TRUE"       // TRUE is synthesizable
    )
   (
    input [N-1:0]  in,         // data to be shifted
    input 	    arithmetic, // shifts in in[N-1] instead of 0
    input 	    right,      // shift right (default is left shift)
    input [S-1:0]   shamt,      // shift amount (unsigned)
    output [N-1:0] out         //shifted output
    );

   generate
      if(SYN=="TRUE")  begin: gbehavioral

	 wire [2*N-1:0] in_sext;
	 wire [N-1:0] 	 sr_result;
	 wire [N-1:0] 	 sl_result;

	 assign shift_in          = arithmetic & in[N-1];

	 assign in_sext[2*N-1:0] = {{(N){shift_in}},in[N-1:0]};

	 assign sr_result[N-1:0] = in_sext[2*N-1:0] >> shamt[S-1:0];

	 assign sl_result[N-1:0] = in[N-1:0]        << shamt[S-1:0];

	 assign out[N-1:0]       = right ? sr_result[N-1:0] :
				            sl_result[N-1:0];

      end // block: gbehavioral
      else begin
	 asic_shift #(.TYPE(TYPE),
		      .N(N))
	 asic_shift (// Outputs
		     .out	 (out[N-1:0]),
		     // Inputs
		     .in	 (in[N-1:0]),
		     .arithmetic (arithmetic),
		     .right      (right),
		     .shamt	 (shamt[S-1:0]));

      end
   endgenerate
endmodule

//#############################################################################
//# Function: Binary adder                                                    #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_add
  #(parameter N    = 32,        // block width
    parameter SYN  = "TRUE",    // synthesizable
    parameter TYPE = "DEFAULT"  // implementation type
    )
   (//inputs
    input [N-1:0]  a, // first operand
    input [N-1:0]  b, // second operand
    input [N-1:0]  k, // carrry kill signal (active high)
    input 	   cin,// carry in
    //outputs
    output [N-1:0] sum,// sum
    output [N-1:0] carry,// complete carry out vector
    output 	   cout// carry out from msb
    );

   generate
      if(SYN == "TRUE")  begin
	 assign {cout,sum[N-1:0]} = a[N-1:0] + b[N-1:0] + cin;
	 //TODO: FIX
	 assign carry = 'b0;
      end
      else begin
	 asic_add #(.TYPE(TYPE),
		    .N(N))
	 asic_add (// Outputs
		   .sum		(sum[N-1:0]),
		   .carry	(carry[N-1:0]),
		   .cout	(cout),
		   // Inputs
		   .a		(a[N-1:0]),
		   .b		(b[N-1:0]),
		   .k		(k[N-1:0]),
		   .cin		(cin));

      end
   endgenerate
endmodule

//#############################################################################
//# Function: Binary multiplier                                               #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_mult
  #(parameter N    = 32,        // block width
    parameter SYN  = "TRUE",    // synthesizable
    parameter TYPE = "DEFAULT"  // implementation type
    )
   (
    //Inputs
    input [N-1:0]    a,       // a input (multiplier)
    input [N-1:0]    b,       // b input (multiplicand)
    input 	      asigned, // a operand is signed
    input 	      bsigned, // b oeprand is signed
    //Outputs
    output [2*N-1:0] product, // a*b final product
    output [2*N-1:0] sum,     // a*b partial sum
    output [2*N-1:0] carry    // a*b partial carry
    );

   generate
      if(SYN=="TRUE")  begin
	 wire a_sext = asigned & a[N-1];
	 wire b_sext = bsigned & b[N-1];
	 assign product[2*N-1:0] = $signed({a_sext,a[N-1:0]}) *
				    $signed({b_sext,b[N-1:0]});
      end
      else begin
	 asic_mult #(.TYPE(TYPE),
		     .N(N))
	 asic_mult (// Outputs
		    .product	(product[2*N-1:0]),
		    .sum	(sum[2*N-1:0]),
		    .carry	(carry[2*N-1:0]),
		    // Inputs
		    .a		(a[N-1:0]),
		    .b		(b[N-1:0]),
		    .asigned	(asigned),
		    .bsigned	(bsigned));

      end
   endgenerate
endmodule

//#############################################################################
//# Function: Carry Save Adder (3:2)                                          #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_csa32
  #(parameter N    = 1,        // vector width
    parameter SYN  = "TRUE",   // synthesizable (or not)
    parameter TYPE = "DEFAULT" // scell type/size
    )
   ( input [N-1:0]  in0, // input
     input [N-1:0]  in1, // input
     input [N-1:0]  in2, // input
     output [N-1:0] s,   // sum
     output [N-1:0] c    // carry
     );

   generate
      if(SYN == "TRUE") begin
	 assign s[N-1:0] = in0[N-1:0] ^ in1[N-1:0] ^ in2[N-1:0];

	 assign c[N-1:0] = (in0[N-1:0] & in1[N-1:0]) |
			   (in1[N-1:0] & in2[N-1:0]) |
			   (in2[N-1:0] & in0[N-1:0] );
      end
      else begin
	 genvar 	     i;
	 for (i=0;i<N;i=i+1) begin
	    asic_csa32 #(.TYPE(TYPE))
	    asic_csa32  (.s(s[i]),
			 .c(c[i]),
			 .in2(in2[i]),
			 .in1(in1[i]),
			 .in0(in0[i]));
	 end
      end
   endgenerate
endmodule

//#############################################################################
//# Function: Carry Save Adder (4:2)                                          #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_csa42
  #(parameter N    = 1,        // number of sync stages
    parameter SYN  = "TRUE",   // synthesizable (or not)
    parameter TYPE = "DEFAULT" // scell type/size
    )
   ( input [N-1:0]  in0,  // input
     input [N-1:0]  in1,  // input
     input [N-1:0]  in2,  // input
     input [N-1:0]  in3,  // input
     input 	    cin,  // intra stage carry in
     output 	    cout, // intra stage carry out (2x sum)
     output [N-1:0] s,    // sum
     output [N-1:0] c     // carry (=2x sum)
     );

   generate
      if(SYN == "TRUE") begin

	 wire [N-1:0]     sum_int;
	 wire [N:0] 	  carry_int;

	 //Edges
	 assign carry_int[0] = cin;
	 assign cout         = carry_int[N];

	 //Full Adders
	 oh_csa32 #(.N(N))
	 fa0 (//inputs
	      .in0(in0[N-1:0]),
	      .in1(in1[N-1:0]),
	      .in2(in2[N-1:0]),
	      //outputs
	      .c(carry_int[N:1]),
	      .s(sum_int[N-1:0]));

	 oh_csa32 #(.N(N))
	 fa1 (//inputs
	      .in0(in3[N-1:0]),
	      .in1(sum_int[N-1:0]),
	      .in2(carry_int[N-1:0]),
	      //outputs
	      .c(c[N-1:0]),
	      .s(s[N-1:0]));
      end
      else begin

	 wire [N-1:0] carry_out;
	 wire [N-1:0] carry_in;

	 assign carry_in[N-1:0] = {carry_out[N-1:1],cin};

	 for (i=1;i<N;i=i+1) begin
	    asic_csa42 #(.TYPE(TYPE))
	    asic_csa42(// Outputs
		       .cout	(carry_out[i]),
		       .s	(s[i]),
		       .c	(c[i]),
		       // Inputs
		       .in0	(in0[i]),
		       .in1	(in1[i]),
		       .in2	(in2[i]),
		       .in3	(in3[i]),
		       .cin	({carry_in[i]}));
	 end

	 assign cout = carry[N-1];

      end
   endgenerate
endmodule // oh_csa42

//#############################################################################
//# Function: Calculates parity value for                                     #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH repository)                         #
//#############################################################################

module oh_parity #( parameter N      = 2 // data width
		 )
   (
    input [N-1:0] in,  // data input
    output 	   out // calculated parity bit
    );

  assign  parity = ^in[N-1:0];

endmodule // oh_parity

//#############################################################################
//# Function: Testbench for "oh_random"
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module testbench
  #(parameter PW        = 256,         // packet total width
    parameter CW        = 16,          // packet control width
    parameter N         = 32,          // ctrl/status width
    parameter DEPTH     = 8192,        // simulus memory depth
    parameter TARGET    = "DEFAULT",   // physical synthesis/sim target
    parameter FILENAME  = "NONE"     // Simulus hexfile for $readmemh
    )
   (
    // control signals to drive
    input 	    nreset, // async active low reset
    input 	    clk, // core clock
    input 	    fastclk, // fast clock
    input 	    slowclk, //slow clock
    input [2:0]     mode, //0=load,1=go,2=bypass,3=rng
    input [N-1:0]   ctrl, // generic ctrl vector
    input [N-1:0]   seed, // seed(s) for rng
    // external write interface
    input 	    ext_clk, //ext packet clock
    input 	    ext_valid, // ext valid signal
    input [PW-1:0]  ext_packet, // ext packet
    input 	    ext_ready, // external ready to receive
    // dut response packets
    output 	    dut_clk, // due packet clock
    output 	    dut_valid, //dut packet valid signal
    output [PW-1:0] dut_packet, // dut packet to drive
    output 	    dut_ready, // dut is ready for packet
    // dut status interface
    output [N-1:0]  dut_status, // generic status vector
    output 	    dut_error,// dut error flag (leads to failure)
    output 	    dut_done, // test done
    output 	    dut_fail  // test failed
    );

   //#################################
   // LOCAL WIRES
   //#################################

   /*AUTOWIRE*/
   /*AUTOINPUT*/

   //#################################
   // DUT LOGIC
   //#################################

   assign dut_ready  = 1'b1;
   assign dut_error  = 1'b0;
   assign dut_done   = 1'b0;
   assign dut_valid  = 1'b0;
   assign dut_clk    = clk;

   oh_lfsr #(.N(N))
   oh_lfsr (// outputs
	    .out      (dut_status[N-1:0] ),
	    // inputs
	    .taps     (ctrl[N-1:0]),
	    .seed     (seed[N-1:0]),
	    .en	      (1'b1),
	    .clk      (clk),
	    .nreset   (nreset));

endmodule // tb
